"""Generated by solo-to-scale; edit `templates/tools/tests/test_release.py` in the plugin, then run upgrade.

The production release: who may release, fast-forward only, and batched or automatic mode.
"""
from __future__ import annotations

import datetime as dt
import json
import subprocess
import sys
from pathlib import Path

TOOLS = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(TOOLS))
import release  # noqa: E402

NOW = dt.datetime(2026, 11, 27, 12, 0, tzinfo=dt.timezone.utc)


def git(cwd: Path, *args: str) -> str:
    return subprocess.run(["git", "-c", "user.name=t", "-c", "user.email=t@example.invalid", "-c", "commit.gpgsign=false",
                           "-c", "init.defaultBranch=main", *args], cwd=cwd, capture_output=True, text=True,
                          check=True).stdout.strip()


def commit(repo: Path, msg: str) -> str:
    (repo / "f.txt").write_text(msg, encoding="utf-8")
    git(repo, "add", "f.txt")
    git(repo, "commit", "-q", "-m", msg)
    git(repo, "push", "-q", "origin", "main")
    return git(repo, "rev-parse", "HEAD")


def repos(tmp_path: Path) -> tuple[Path, Path]:
    remote, work = tmp_path / "remote.git", tmp_path / "work"
    git(tmp_path, "init", "-q", "--bare", str(remote))
    git(tmp_path, "init", "-q", str(work))
    git(work, "remote", "add", "origin", str(remote))
    for k, v in (("user.name", "t"), ("user.email", "t@example.invalid"), ("commit.gpgsign", "false"),
                 ("tag.gpgsign", "false")):
        git(work, "config", k, v)
    return remote, work


def test_only_a_founder_runs_it_and_a_merge_releases_only_in_automatic_mode(tmp_path):
    (tmp_path / "founder").mkdir()
    (tmp_path / "founder" / "gates.json").write_text(json.dumps({"founders": ["Ada"]}), encoding="utf-8")
    assert release.may_release("ada", "workflow_dispatch", False, tmp_path, "acme/x")[0]
    assert not release.may_release("acme", "workflow_dispatch", True, tmp_path, "acme/x")[0], "founders list wins"
    assert not release.may_release("claude[bot]", "workflow_dispatch", True, tmp_path, "acme/x")[0]
    assert not release.may_release("ada", "push", False, tmp_path, "acme/x")[0], "batched: a merge never releases"
    assert release.may_release("anyone", "push", True, tmp_path, "acme/x")[0], "automatic: every merge releases"
    assert not release.may_release("ada", "pull_request", True, tmp_path, "acme/x")[0]
    (tmp_path / "founder" / "gates.json").write_text("{}", encoding="utf-8")
    assert release.may_release("acme", "workflow_dispatch", False, tmp_path, "acme/x")[0], "no list: the owner"


def test_a_release_moves_production_to_main_lists_the_changes_and_tags_it(tmp_path):
    remote, work = repos(tmp_path)
    first = commit(work, "one")
    summary = tmp_path / "summary.md"
    assert release.run(work, "main", str(summary), False, now=NOW) == release.OK
    assert git(remote, "rev-parse", "production") == first
    commit(work, "PR two (#2)")
    head = commit(work, "PR three (#3)")
    assert release.run(work, "main", str(summary), True, now=NOW) == release.OK
    assert git(remote, "rev-parse", "production") == first, "a dry run pushes nothing"
    later = NOW + dt.timedelta(hours=1)
    assert release.run(work, "main", str(summary), False, now=later) == release.OK
    assert git(remote, "rev-parse", "production") == head
    assert git(remote, "rev-parse", "release-20261127-1300^" + "{commit}") == head
    text = summary.read_text(encoding="utf-8")
    assert "2 change(s)" in text and "PR two (#2)" in text and "PR three (#3)" in text
    assert release.run(work, "main", str(summary), False, now=later) == release.OK
    assert "Nothing to release" in summary.read_text(encoding="utf-8")


def test_it_fails_closed_when_production_moved_away_or_the_ref_is_not_on_main(tmp_path):
    remote, work = repos(tmp_path)
    commit(work, "one")
    assert release.run(work, "main", None, False, now=NOW) == release.OK
    assert release.run(work, "main; rm -rf /", None, False) == release.ERROR
    git(work, "checkout", "-q", "-b", "side")
    (work / "g.txt").write_text("x", encoding="utf-8")
    git(work, "add", "g.txt")
    git(work, "commit", "-q", "-m", "not on main")
    side = git(work, "rev-parse", "HEAD")
    assert release.run(work, side, None, False) == release.ERROR
    git(work, "push", "-q", "-f", "origin", "side:production")
    git(work, "checkout", "-q", "main")
    commit(work, "two")
    assert release.run(work, "main", None, False) == release.ERROR, "production has work main lacks"
    assert git(remote, "rev-parse", "production") == side


def test_the_workflow_releases_on_a_founders_run_or_a_merge_in_automatic_mode():
    wf = TOOLS.parent / ".github" / "workflows" / "deploy-release.yml"
    if not wf.exists():
        return
    text = wf.read_text(encoding="utf-8")
    assert "workflow_dispatch:" in text and "branches: [main]" in text and "pull_request" not in text
    assert "if: github.event_name == 'workflow_dispatch' || vars.S2S_AUTO_RELEASE == 'true'" in text
    assert "tools/release.py check" in text and "tools/release.py run" in text
    assert "${{ github.event.inputs.ref" not in text.split("run:")[-1], "the ref reaches the shell only as an env var"
